def run(story, chapters, report):
    title = story.get("title") or "Untitled"
    parts = ["# " + title]

    for chapter in chapters:
        heading = "## Chapter " + str(chapter["number"])

        if chapter.get("title"):
            heading = heading + ": " + chapter["title"]

        parts.append(heading + "\n\n" + chapter["text"])

    return {
        "novel": {
            "title": title,
            "chapters": chapters,
            "markdown": "\n\n".join(parts) + "\n",
            "report": report,
        }
    }
